package org.eclipse.rdf4j.query.algebra.helpers;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Exists;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.Lateral;
import org.eclipse.rdf4j.query.algebra.Not;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.ValueExpr;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

class InputMetadataObservationTest {
	private static final String INPUT = "callerInput";

	@Test
	void lateralOriginalNameMembershipCannotBeSilentlyCertifiedAway() {
		Lateral lateral = new Lateral(new SingletonSet(), new SingletonSet(), Set.of(INPUT));
		assertThat(lateral.getBindingNames()).isEmpty();
		assertThat(lateral.getAssuredBindingNames()).isEmpty();
		assertMetadataObserved(lateral);
	}

	@Test
	void filterRequiredInputCertificateCannotBeSilentlyCertifiedAway() {
		Filter filter = constantFilter();
		filter.setRequiredInputBindingNames(Set.of(INPUT));
		assertThat(filter.getBindingNames()).isEmpty();
		assertThat(filter.getAssuredBindingNames()).isEmpty();
		assertThat(QueryAlgebraBindingAnalysis.withBindingValues(filter, EmptyBindingSet.getInstance())
				.requiredInputBindingNames(filter)).containsExactly(INPUT);
		assertMetadataObserved(filter);
	}

	@Test
	void ordinaryMetadataFreeNodesKeepTheirCompleteEmptyDomain() {
		for (TupleExpr expression : List.of(new Lateral(new SingletonSet(), new SingletonSet(), Set.of()),
				constantFilter())) {
			TupleExprs.ConditionBindingDomain observed = TupleExprs.tupleBindingObservationDomain(expression);
			assertThat(observed.known()).isTrue();
			assertThat(observed.names()).isEmpty();
			assertThat(TupleExprs.conditionFrameContainsAllObservations(observed, Set.of())).isTrue();
		}
	}

	private static void assertMetadataObserved(TupleExpr expression) {
		TupleExprs.ConditionBindingDomain direct = TupleExprs.tupleBindingObservationDomain(expression);
		assertThat(!direct.known() || direct.names().contains(INPUT))
				.as("unvisited executable input metadata needs a name proof or conservative unknown")
				.isTrue();
		for (ValueExpr condition : List.of(new Exists(expression.clone()),
				new Not(new Exists(expression.clone())),
				new Exists(new Filter(new SingletonSet(), new Not(new Exists(expression.clone())))))) {
			TupleExprs.ConditionBindingDomain observed = TupleExprs.conditionBindingDomain(condition);
			assertThat(!observed.known() || observed.names().contains(INPUT)).isTrue();
			assertThat(TupleExprs.conditionFrameContainsAllObservations(observed, Set.of())).isFalse();
		}
	}

	private static Filter constantFilter() {
		return new Filter(new SingletonSet(),
				new ValueConstant(SimpleValueFactory.getInstance().createLiteral(true)));
	}
}
